<template>
  <div class="me-favorite-body" v-title data-title="卫星地面融合网络社区-我的收藏">
    <div class="me-favorite-container">
      <header class="me-favorite-header">
        <h1 class="me-favorite-title">我的收藏</h1>
        <p class="me-favorite-desc">共收藏了 {{favorites.length}} 篇文章</p>
      </header>

      <main class="me-favorite-main">
        <div v-if="favorites.length === 0" class="empty-state">
          <div class="empty-icon">📚</div>
          <p class="empty-text">暂无收藏文章</p>
          <el-button type="primary" @click="goHome">去看看文章</el-button>
        </div>

        <div v-else class="favorite-list">
          <article-item 
            v-for="article in favorites" 
            :key="article.id" 
            v-bind="article">
          </article-item>
        </div>
      </main>
    </div>
  </div>
</template>

<script>
  import ArticleItem from '@/components/article/ArticleItem'
  import {getFavorites} from '@/api/favorite'

  export default {
    name: 'BlogFavorite',
    created() {
      this.loadFavorites()
    },
    data() {
      return {
        favorites: []
      }
    },
    methods: {
      loadFavorites() {
        let that = this
        getFavorites().then(data => {
          if (data && data.data) {
            that.favorites = data.data
          }
        }).catch(error => {
          if (error !== 'error') {
            that.$message({type: 'error', message: '收藏列表加载失败', showClose: true})
          }
        })
      },
      goHome() {
        this.$router.push({path: '/'})
      }
    },
    components: {
      ArticleItem
    }
  }
</script>

<style scoped>
  .me-favorite-body {
    margin: 80px auto 140px;
    padding: 0 20px;
  }

  .me-favorite-container {
    max-width: 800px;
    margin: 0 auto;
    width: 100%;
  }

  .me-favorite-header {
    text-align: center;
    padding: 40px 0;
    border-bottom: 1px solid #f0f0f0;
    margin-bottom: 30px;
  }

  .me-favorite-title {
    font-size: 28px;
    font-weight: 700;
    color: #333;
    margin: 0 0 10px 0;
  }

  .me-favorite-desc {
    font-size: 14px;
    color: #969696;
    margin: 0;
  }

  .me-favorite-main {
    background: #fff;
    border-radius: 8px;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
    overflow: hidden;
    padding: 20px;
  }

  .empty-state {
    text-align: center;
    padding: 60px 20px;
  }

  .empty-icon {
    font-size: 64px;
    margin-bottom: 20px;
  }

  .empty-text {
    font-size: 16px;
    color: #969696;
    margin: 0 0 20px 0;
  }

  .favorite-list {
    padding: 10px;
  }

  @media screen and (max-width: 767px) {
    .me-favorite-body {
      margin: 70px auto 120px;
      padding: 0 15px;
    }

    .me-favorite-title {
      font-size: 22px;
    }

    .me-favorite-header {
      padding: 30px 0;
    }

    .empty-state {
      padding: 40px 20px;
    }
  }
</style>


